let language = 'zh';
export const languageStorageKey = 'ifc-regulation-workbench.language.v1';
export function getLanguage() { return language; }
export function setLanguage(value) { language = value === 'en' ? 'en' : 'zh'; }
export function t(key, params = {}) {
  let template = language === 'en' ? english[key] ?? key : key;
  if (language === 'en' && params.n === 1) {
    template = template.replace(/\bobjects\b/g, 'object').replace(/\bentries\b/g, 'entry').replace(/\blinks\b/g, 'link');
  }
  return template.replace(/\{(\w+)\}/g, (_, name) => String(params[name] ?? `{${name}}`));
}
export function linkReason(reason) {
  const direct = reason.match(/^现有候选映射：(.*?) → (.*)$/);
  if (direct) return t('现有候选映射：{concept} → {types}', {concept:direct[1], types:direct[2]});
  const descendant = reason.match(/^条款 (.*?) 的子条款或例外；需核验用途条件$/);
  if (descendant) return t('条款 {clause} 的子条款或例外；需核验用途条件', {clause:descendant[1]});
  const context = reason.match(/^条款 (.*?) 的上位条款、例外或引用上下文$/);
  if (context) return t('条款 {clause} 的上位条款、例外或引用上下文', {clause:context[1]});
  return t(reason);
}
